Console.WriteLine("""
{
  "apiVersion": "topology.intropy.io/v1",
  "kind": "SystemTopology",
  "system": "contract-demo",
  "components": [
    {
      "name": "demo-extractor",
      "kind": "extractor",
      "publishes": [{ "pubsub": "pubsub", "topic": "demo-orders" }]
    }
  ],
  "topics": [
    {
      "pubsub": "pubsub",
      "topic": "demo-orders",
      "contract": "Demo.Contracts.Order",
      "publishers": ["demo-extractor"]
    }
  ],
  "contracts": [
    {
      "name": "Demo.Contracts.Order",
      "kind": "event",
      "shortName": "Order",
      "mediaType": "application/json",
      "fingerprint": "sha256:9f2a41c803de11ab",
      "schema": {
        "type": "object",
        "properties": {
          "orderId": { "type": "string" },
          "customerId": { "type": "string" },
          "orderDate": { "type": "string", "format": "date-time" },
          "note": { "type": ["string", "null"] },
          "lines": { "type": "array", "items": { "$ref": "#/$defs/OrderLine" } }
        },
        "required": ["orderId", "customerId", "orderDate", "lines"],
        "$defs": {
          "OrderLine": {
            "type": "object",
            "properties": {
              "sku": { "type": "string" },
              "quantity": { "type": "integer" },
              "unitPrice": { "type": "number" }
            },
            "required": ["sku"]
          }
        }
      }
    }
  ]
}
""");
EOF
